// function doneCount()
int Main::doneCount()
{
    auto *self = this;
    (void)self;
    int l_n = 0;
    for (int l_i = 0; (l_i < self->todoModel.count.get()); l_i = (l_i + 1)) {
        if (((void)self->todoModel.revision.get(), mq::js::listAt(self->todoModel_rows, self->todoModel_size, l_i)).done) {
            l_n = (l_n + 1);
        }
    }
    return l_n;
    return 0;
}

