// Loader: (re)creates the selected component in place
void Main::_ld44_load(void *ctx)
{
    auto *self = static_cast<Main *>(ctx);
    self->_o27.unload();
    switch (self->_ld44_which.value()) {
    case 0: {
        auto *obj = new (self->_ld44_buf.data) Main_Delegate7();
        obj->mq_setup(self);
        self->_o27.attach(obj, obj, [](void *p) { static_cast<Main_Delegate7 *>(p)->~Main_Delegate7(); });
        obj->componentComplete();
        break;
    }
    case 1: {
        auto *obj = new (self->_ld44_buf.data) Main_Delegate8();
        obj->mq_setup(self);
        self->_o27.attach(obj, obj, [](void *p) { static_cast<Main_Delegate8 *>(p)->~Main_Delegate8(); });
        obj->componentComplete();
        break;
    }
    default: break;
    }
}

