// shows the delegates of the Repeater rows, hides the others
void Main::_pool46_update(void *ctx)
{
    auto *self = static_cast<Main *>(ctx);
    const int n = self->_o32.count.value();
    for (int i = 0; i < 3; ++i) {
        if (i < n) _pool46_bind(self, &self->_pool46[i], i);
        self->_pool46[i].visible.setValue(i < n);
    }
}

