// function addTask()
void Main::addTask()
{
    auto *self = this;
    (void)self;
    (*self).added.set(((*self).added.get() + 1));
    { mq::js::listInsert(self->todoModel_rows, self->todoModel_size, self->todoModel_size, Main::todoModel_Row{(mq::String::lit("New task ") + (*self).added.get()), mq::String::lit("Added"), false}); self->todoModel.changed(self->todoModel_size); };
    self->todoList.currentIndex.set((self->todoModel.count.get() - 1));
    self->todoList.positionViewAt((self->todoModel.count.get() - 1), 2);
}

// onClicked
void Main::_c81_fn(void *ctx)
{
    auto *self = static_cast<Main *>(ctx);
    (void)self;
    (*self).addTask();
}

