// dependency links for every binding of the application (estimated)
#ifdef MQ_APP_PLATFORM_STORAGE
// The platform provides the memory once at startup (e.g. from the internal
// heap when the static RAM segment is too small, as on the ESP32).
void *mq_platform_alloc(size_t size, size_t align);
#else
static mq::Link mq_link_pool[743];
#endif

mq::Item *mq_app_root()
{
#ifdef MQ_APP_PLATFORM_STORAGE
    static mq::Link *mq_link_pool = new (mq_platform_alloc(sizeof(mq::Link) * 743, alignof(mq::Link))) mq::Link[743];
#endif
    static bool poolRegistered = (mq::registerLinkPool(mq_link_pool, 743), true);
    (void)poolRegistered;
    mq::registerImages(mq_images, 1);
    static bool fontsRegistered = (mq::registerFonts(mq_fonts, mq_font_count), true);
    (void)fontsRegistered;
#ifdef MQ_APP_PLATFORM_STORAGE
    static Main &root = *new (mq_platform_alloc(sizeof(Main), alignof(Main))) Main;
#else
    static Main root;
#endif
    static bool completed = (root.componentComplete(), true);
    (void)completed;
    return &root;
}
